@use 'buttons';
@use 'colors';

.dashboard-app.theme-default {
  // Dashboard, dashboard-app, powerups-selector
  .dashboard-app,
  .dashboard,
  .powerups-selector {
    // No color/typography/border-radius here
  }

  // Dashboard title
  .dashboard-title {
    font-size: 2em;
    text-transform: uppercase;
    background-color: colors.$c-fluo-green;
    color: black;

    h2 {
      font-size: 2em;
      color: black;
      text-transform: uppercase;
    }
  }

  // Dashboard
  .dashboard {
    background-color: #fff;

    .citizen-requests {
      font-size: 1.4em;
    }
    .index-list {
      font-size: 1.9em;
    }
    .dashboard-title {
      font-size: 2em;
    }
  }

  // Dashboard action button
  .btn-dashboard-action {
    font-size: 1.8em;
    border-radius: 6em;

    .text-main {
      font-weight: bold;
      font-size: 1.2em;
      &::first-line {
        font-size: 1.3em;
      }
    }
    .text-translation {
      font-size: 1.1em;
    }
    &.disabled, &:disabled {
      color: rgb(255 255 255 / 65%)!important;
    }
  }

  // Button variants (using mixin)
  .btn-show-pollution {
    @include buttons.button-variant(#ffffff, colors.$c-cherry, colors.$c-cherry);
  }
  .btn-show-noise {
    @include buttons.button-variant(#ffffff, colors.$c-grape, colors.$c-grape);
  }
  .btn-power-ups-activate {
    @include buttons.button-variant(#ffffff, colors.$c-mint, colors.$c-mint);
    &.disabled {
      // No color/typography/border-radius here
    }
  }
  .btn-cancel {
    @include buttons.button-variant(#ffffff, colors.$c-gray-mid, colors.$c-gray-mid);
    color: black;
  }
}
